// CrossScoreDelta 跨服分数变更通知：A 服改不了 B 服玩家的分，只能请 B 服自己改。
//
// 走 NodeReport.cross_delta → 中心服转成 CenterCommand.cross_score → B 服的
// 专用字段，而不复用 RelayRequest。差别在**中心服看不看得见这条消息**：
// relay 是纯透传（payload 原样投递，中心服不解包），而改分是玩法里的资金类
// 操作，中心服至少要有计数与「目标节点不存在」的丢弃日志，出问题时才有观测点。
//
// 必须传差值而不是绝对值：A 服手上的绝对值是 60s 前的快照，直接覆盖会抹掉
// B 服本地刚产生的增量。
type CrossScoreDelta struct {
	state         protoimpl.MessageState
	sizeCache     protoimpl.SizeCache
	unknownFields protoimpl.UnknownFields

	RelayId    string `protobuf:"bytes,1,opt,name=relay_id,json=relayId,proto3" json:"relay_id,omitempty"`     // 幂等键 sd:{node}:{seq}，接收方按 (from_node, relay_id) 去重
	PlayerId   int64  `protobuf:"varint,2,opt,name=player_id,json=playerId,proto3" json:"player_id,omitempty"` // 被改分的目标玩家（归属于收件方）
	Delta      int64  `protobuf:"varint,3,opt,name=delta,proto3" json:"delta,omitempty"`                       // 负值=扣分
	GroupId    int32  `protobuf:"varint,4,opt,name=group_id,json=groupId,proto3" json:"group_id,omitempty"`
	FromPlayer int64  `protobuf:"varint,5,opt,name=from_player,json=fromPlayer,proto3" json:"from_player,omitempty"` // 攻击发起者（审计用）
	FromNode   string `protobuf:"bytes,6,opt,name=from_node,json=fromNode,proto3" json:"from_node,omitempty"`        // 发起方节点；中心服转发时回填，接收方据此去重与审计
	// to_server 目标玩家的区服编号（不是节点 ID）。
	//
	// 游戏服只知道玩家的 server_id（表里存的就是它），不知道承载那个服的
	// 部署态 node_id——那个映射只有中心服有（registry.NodeIDForServer）。
	// 所以这里传业务标识，由中心服反查路由，游戏服不需要维护映射。
	ToServer int32 `protobuf:"varint,7,opt,name=to_server,json=toServer,proto3" json:"to_server,omitempty"`
}

